  const [transcendFruitDebugMasuId, setTranscendFruitDebugMasuId] = useState(null);
  const [transcendFruitDebugItemId, setTranscendFruitDebugItemId] = useState('');
  const [transcendFruitDebugResult, setTranscendFruitDebugResult] = useState(null);
  const [dyeMaskEditorOpened, setDyeMaskEditorOpened] = useState(false);
  const [temporaryDyeMasks, setTemporaryDyeMasks] = useState({});
  const temporaryDyeMasksRef = useRef({});
  useEffect(()=>()=>{Object.values(temporaryDyeMasksRef.current).forEach(URL.revokeObjectURL);temporaryDyeMasksRef.current={};},[]);
  const releaseTemporaryDyeMask = (baseId) => {
    const url=temporaryDyeMasksRef.current[baseId];if(!url)return;
    URL.revokeObjectURL(url);delete temporaryDyeMasksRef.current[baseId];
    delete _temporaryDyeMasks[baseId];setTemporaryDyeMasks({...temporaryDyeMasksRef.current});
  };
  const releaseAllTemporaryDyeMasks = () => {
    if(Object.keys(temporaryDyeMasksRef.current).length&&!window.confirm('全モンスターの一時マスクを解除しますか？'))return;
    Object.keys(temporaryDyeMasksRef.current).forEach(releaseTemporaryDyeMask);
  };
  const tryTemporaryDyeMask = (target,blob,colors) => {
    releaseTemporaryDyeMask(target.baseId);
    const url=URL.createObjectURL(blob);temporaryDyeMasksRef.current[target.baseId]=url;_temporaryDyeMasks[target.baseId]=url;
    setTemporaryDyeMasks({...temporaryDyeMasksRef.current});
    const individual=masuMons.find(m=>m.baseId===target.baseId),preview=individual||{id:`temporary-dye-${target.baseId}`,baseId:target.baseId,name:target.name,colors:[]};
    setMonsterImageDebugId(preview.id);setMonsterImageDebugColors(colors||getMasuColors(preview));setGameState('MONSTER_IMAGE_DEBUG');
  };
  // バトルチュートリアル(操作しながら覚える)。null のときは動いていない。
