  const tutorialShownRef = useRef(false);
  const battleTutorialGuideCheckedRef = useRef(false);
  const highScoresRef = useRef({});
  useEffect(() => { highScoresRef.current = highScores; }, [highScores]);
  const [attemptCounts, setAttemptCounts] = useState({}); // 難易度別 挑戦回数(端末保存)
  const [clearCounts, setClearCounts] = useState({}); // 難易度別 クリア回数(端末保存)
  const [highestWaves, setHighestWaves] = useState({});
  // 極限チャレンジ(EXTREME)の記録。チャレンジの mh_hs_* / mh_clears_* とは別のキーへ持つ
  const [extremeBestScores, setExtremeBestScores] = useState({});
  const [extremeClearCounts, setExtremeClearCounts] = useState({});
  const [extremeDifficultyClearCounts, setExtremeDifficultyClearCounts] = useState({});
  const [onboarded, setOnboarded] = useState(true); // false=初回起動(プロフィール設定へ誘導)
  // 遊んだ時間を数える。画面が見えているあいだだけ進み、離れるときと60秒ごとに保存する。
  useEffect(() => {
    let disposed = false;
    let last = Date.now();
    let sinceLastSave = 0;
    const persist = () => {
      const value = playtimeRef.current;
      storeSet(PLAYTIME_KEY, {
        totalMs: Math.round(value.totalMs), since: value.since, days: value.days,
        today: { day: value.today.day, ms: Math.round(value.today.ms) },
        longest: { day: value.longest.day, ms: Math.round(value.longest.ms) },
      }, false);
      sinceLastSave = 0;
    };
    const accumulate = () => {
      const now = Date.now();
      const delta = now - last;
      last = now;
      if (typeof document !== 'undefined' && document.visibilityState !== 'visible') return;
      // スリープ・端末の時計合わせなどで大きく飛んだぶんは、遊んでいた時間ではないので数えない
      if (!(delta > 0 && delta <= PLAYTIME_MAX_STEP_MS)) return;
      playtimeRef.current = advancePlaytime(playtimeRef.current, delta, now);
      sinceLastSave += delta;
      if (sinceLastSave >= PLAYTIME_SAVE_MS) persist();
    };
    const onVisibility = () => {
      if (typeof document === 'undefined') return;
      if (document.visibilityState === 'visible') last = Date.now();
      else { accumulate(); persist(); }
    };
    (async () => {
      const saved = normalizePlaytime(await storeGet(PLAYTIME_KEY, null, false));
      if (disposed) return;
      // 読み込みの前に数えたぶんがあれば足しておく(読み込みを待つあいだも遊んでいるため)
      playtimeRef.current = advancePlaytime(saved, playtimeRef.current.totalMs);
      last = Date.now();
    })();
    const timer = setInterval(accumulate, PLAYTIME_TICK_MS);
    if (typeof document !== 'undefined') document.addEventListener('visibilitychange', onVisibility);
    return () => {
      disposed = true;
      clearInterval(timer);
      if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', onVisibility);
      accumulate();
      persist();
    };
  }, []);
  // プロフィールを開いたときだけ、いまの値を画面へ写す
  useEffect(() => {
    if (gameState !== 'PROFILE') return;
    setPlaytimeView({ ...playtimeRef.current });
  }, [gameState]);
  const [onboardingName, setOnboardingName] = useState('');
  const [onboardingIcon, setOnboardingIcon] = useState(null);
  const [showWaveDetails, setShowWaveDetails] = useState(false);
  // 極限の「ルール詳細」で開いている難易度ID。開いても選択中の難易度やバトル開始状態は変えない
  const [extremeRuleDetail, setExtremeRuleDetail] = useState(null);
