      let wasOnboarded = await storeGet('mh_onboarded', null, false);
      const hasSavedName = typeof savedName==='string' && savedName.trim() && savedName!=='名無しのブリーダー';
      const hasSavedIcon = typeof savedIcon==='string' && savedIcon.length>0;
