      const everOnboarded = wasOnboarded === true;
      if (wasOnboarded && !(hasSavedName && hasSavedIcon)) wasOnboarded = false;
      setOnboarded(wasOnboarded);
      setNewPlayerCampaignEligible(!everOnboarded);
      // 助手選択は、はじめて遊ぶ人にだけ出す。
