  const [tutorialPanelAtTop, setTutorialPanelAtTop] = useState(false);
  useEffect(() => {
    if (tutorialStep == null || !tutorialSpot) { setTutorialPanelAtTop(false); return; }
    // 光らせた要素が描かれてから測る
    const id = requestAnimationFrame(() => {
      try {
        const els = document.querySelectorAll('.is-tutorial-spot');
        const height = window.innerHeight || 0;
        let bottom = -Infinity;
        els.forEach(el => {
          // 施設は当たり判定の枠が広く、実際に見えているのは中のラベルなので、そちらを測る
          const target = el.classList.contains('mh-home-facility') ? (el.querySelector('span') || el) : el;
          const r = target.getBoundingClientRect();
          if (r.height > 0) bottom = Math.max(bottom, r.bottom);
        });
        setTutorialPanelAtTop(height > 0 && bottom > height * 0.5);
      } catch { setTutorialPanelAtTop(false); }
    });
    return () => cancelAnimationFrame(id);
  }, [tutorialStep, tutorialSpot]);
  const startTutorial = (kind = 'tour') => { tutorialShownRef.current = true; setShowTitleSettings(false); setTutorialKind(kind); setTutorialStep(0); };
